class Solution:
    def maxProduct(self, nums, k, limit):
        total = sum(nums)
        if k > total or k < -total:
            return -1

        EXC = -1  # sentinel: product exceeds limit
        dp = {}  # (alt_sum, parity) -> set of products (may include EXC)

        for x in nums:
            extensions = {}
            for (s, par), prods in dp.items():
                new_par = 1 - par
                new_s = s + x if par == 0 else s - x
                if x == 0:
                    new_prods = {0}
                elif x == 1:
                    new_prods = set(prods)
                else:
                    new_prods = set()
                    has_exc = False
                    for p in prods:
                        if p == EXC:
                            has_exc = True
                            continue
                        np = p * x
                        if np <= limit:
                            new_prods.add(np)
                        else:
                            has_exc = True
                    if has_exc:
                        new_prods.add(EXC)
                    if not new_prods:
                        continue
                key = (new_s, new_par)
                if key in extensions:
                    extensions[key] |= new_prods
                else:
                    extensions[key] = new_prods

            # Start new subsequence with x as first element
            key = (x, 1)
            new_prod = x if x <= limit else EXC
            if key in extensions:
                extensions[key].add(new_prod)
            else:
                extensions[key] = {new_prod}

            # Merge extensions into dp (skip transition keeps dp as is)
            for key, ext_prods in extensions.items():
                if key in dp:
                    dp[key] |= ext_prods
                else:
                    dp[key] = ext_prods

        best = -1
        for par in range(2):
            key = (k, par)
            if key in dp:
                for p in dp[key]:
                    if p != EXC and p > best:
                        best = p
        return best
